// Demo data for static GitHub Pages demo mode.
// All dates are computed relative to now so the demo always looks current.

const MS_PER_DAY = 86_400_000;
const now = new Date();
now.setHours(7, 30, 0, 0);

function daysAgo(n) {
  return new Date(now.getTime() - n * MS_PER_DAY);
}
function iso(d) {
  return d.toISOString().replace(".000Z", "Z");
}
function dateStr(d) {
  return d.toISOString().slice(0, 10);
}
function uid(n) {
  return `00000000-0000-4000-8000-${String(n).padStart(12, "0")}`;
}

