function pickName(routeKey, idx) {
  const opts = NAMES[routeKey];
  return opts[idx % opts.length];
}

export const ACTIVITIES = ACTIVITY_DEFS.map((def, idx) => {
  const [days, sport, route, distKm, elapsedMin, avgHR, maxHR, elevGain] = def;
  const startAt = daysAgo(days);
  const elapsedMs = elapsedMin * 60_000;
  const endAt = new Date(startAt.getTime() + elapsedMs);
  const distM = distKm * 1000;
  const paceSecPerKm = (elapsedMin * 60) / distKm;
  const speedMps = distM / (elapsedMin * 60);
  const calories = sport === "run"
    ? Math.round(elapsedMin * 10.5)
    : Math.round(elapsedMin * 8.5);

  return {
    id: uid(idx + 1),
    sport_type: sport,
    name: pickName(route, idx),
    start_at: iso(startAt),
    end_at: iso(endAt),
    elapsed_ms: elapsedMs,
    moving_ms: Math.round(elapsedMs * 0.96),
    distance_meters: distM,
    elevation_gain_meters: elevGain,
    average_heart_rate: avgHR,
    max_heart_rate: maxHR,
    average_speed_meters_per_second: speedMps,
    average_pace_seconds_per_km: paceSecPerKm,
    calories,
    indoor: false,
    laps: buildLaps(startAt, distKm, elapsedMin, avgHR, maxHR),
    tags: idx === 0 ? [{ key: "feel", value: "great" }] : [],
    _route: route,
    _routeCoords: ROUTES[route],
    _samples: SAMPLES[route],
  };
});

function buildLaps(startAt, distKm, elapsedMin, avgHR, maxHR) {
  const lapLen = 1.0; // 1 km laps
  const nLaps = Math.floor(distKm);
  const secPerKm = (elapsedMin * 60) / distKm;
  return Array.from({ length: nLaps }, (_, i) => {
    const lapStart = new Date(startAt.getTime() + i * secPerKm * 1000);
    const lapEnd = new Date(lapStart.getTime() + secPerKm * 1000);
    return {
      index: i + 1,
      start_at: iso(lapStart),
      end_at: iso(lapEnd),
      duration_ms: Math.round(secPerKm * 1000),
      distance_meters: 1000,
      average_heart_rate: avgHR + (Math.random() * 6 - 3),
      max_heart_rate: maxHR - Math.round(Math.random() * 5),
    };
  });
}

// ── GPS Samples for a detailed activity (first activity) ─────────────────────

export function buildSamples(activity) {
  const coords = activity._routeCoords;
  const series = activity._samples;
  const startMs = new Date(activity.start_at).getTime();
  return coords.map((coord, i) => {
    const [ele, hr, cad, distM, elapsedS] = series[i];
    // Real per-segment speed (organic, grade-driven) — not a synthesized curve.
    let speed = activity.average_speed_meters_per_second;
    if (i > 0) {
      const prev = series[i - 1];
      const dt = elapsedS - prev[4];
      const dd = distM - prev[3];
      if (dt > 0) speed = dd / dt;
    }
    return {
      sample_at: iso(new Date(startMs + elapsedS * 1000)),
      elapsed_ms: elapsedS * 1000,
      latitude: coord[0],
      longitude: coord[1],
      distance_meters: distM,
      elevation_meters: ele,
      heart_rate: hr,
      speed_meters_per_second: speed,
      cadence: activity.sport_type === "run" && cad ? cad : null,
    };
  });
}

