// ── Stats ─────────────────────────────────────────────────────────────────────

function computeStats(acts) {
  const runs = acts.filter(a => a.sport_type === "run");
  const rides = acts.filter(a => a.sport_type === "ride");
  const totalDist = acts.reduce((s, a) => s + a.distance_meters, 0);
  const totalMs   = acts.reduce((s, a) => s + a.elapsed_ms, 0);
  const totalCal  = acts.reduce((s, a) => s + (a.calories || 0), 0);
  const avgPace   = runs.reduce((s, a) => s + a.average_pace_seconds_per_km, 0) / (runs.length || 1);
  const avgHR     = acts.reduce((s, a) => s + a.average_heart_rate, 0) / (acts.length || 1);
  return {
    total_activities: acts.length,
    total_distance_meters: totalDist,
    total_elapsed_ms: totalMs,
    total_calories: totalCal,
    avg_pace_seconds_per_km: avgPace,
    avg_heart_rate: avgHR,
    by_sport: [
      { sport_type: "run",  activity_count: runs.length,  distance_meters: runs.reduce((s,a)=>s+a.distance_meters,0) },
      { sport_type: "ride", activity_count: rides.length, distance_meters: rides.reduce((s,a)=>s+a.distance_meters,0) },
    ],
  };
}

export function getStats(from, to) {
  const acts = filterByDate(ACTIVITIES, from, to);
  return computeStats(acts);
}

function filterByDate(acts, from, to) {
  return acts.filter(a => {
    const t = new Date(a.start_at).getTime();
    if (from && t < new Date(from).getTime()) return false;
    if (to   && t > new Date(to).getTime())   return false;
    return true;
  });
}

// ── Timeseries ────────────────────────────────────────────────────────────────

export function getTimeseries(granularity, from, to) {
  // Generate weekly buckets for the past 52 weeks
  const weeks = 52;
  const buckets = [];
  for (let w = weeks - 1; w >= 0; w--) {
    const weekStart = daysAgo(w * 7 + 6);
    weekStart.setHours(0, 0, 0, 0);
    const weekEnd = daysAgo(w * 7);

    const acts = ACTIVITIES.filter(a => {
      const t = new Date(a.start_at).getTime();
      return t >= weekStart.getTime() && t <= weekEnd.getTime();
    });

    const dist = acts.reduce((s, a) => s + a.distance_meters, 0);
    const avgPace = acts.length
      ? acts.filter(a=>a.sport_type==="run").reduce((s,a)=>s+a.average_pace_seconds_per_km,0) / (acts.filter(a=>a.sport_type==="run").length || 1)
      : null;
    const avgHR = acts.length
      ? acts.reduce((s,a)=>s+a.average_heart_rate,0)/acts.length
      : null;

    buckets.push({
      period_start: weekStart.toISOString().replace(".000Z", "Z"),
      distance_meters: dist,
      activity_count: acts.length,
      avg_pace_seconds_per_km: avgPace || undefined,
      avg_heart_rate: avgHR || undefined,
    });
  }
  return buckets;
}

// ── PMC ───────────────────────────────────────────────────────────────────────

export function getPMC(from, to) {
  const days = 365;
  let ctl = 0, atl = 0;
  const result = [];

  for (let d = days - 1; d >= 0; d--) {
    const day = daysAgo(d);
    const dayStr = dateStr(day);
    const acts = ACTIVITIES.filter(a => a.start_at.slice(0, 10) === dayStr);
    const trimp = acts.reduce((s, a) => {
      // simplified TRIMP: duration_h * avgHR_fraction * 1.92
      const h = a.elapsed_ms / 3_600_000;
      const hrFrac = (a.average_heart_rate - 50) / (195 - 50);
      return s + h * hrFrac * 100 * 1.92;
    }, 0);

    ctl = ctl + (trimp - ctl) / 42;
    atl = atl + (trimp - atl) / 7;
    const tsb = ctl - atl;

    result.push({ date: dayStr, trimp: Math.round(trimp * 10) / 10, ctl: Math.round(ctl * 10) / 10, atl: Math.round(atl * 10) / 10, tsb: Math.round(tsb * 10) / 10 });
  }
  return result;
}

// ── Records (best efforts) ────────────────────────────────────────────────────

const STANDARD_DISTANCES = [400, 1000, 1609, 5000, 10000, 21097];

export function getRecords(sportType) {
  const runs = ACTIVITIES.filter(a => a.sport_type === (sportType || "run") && a.sport_type === "run");
  if (!runs.length) return [];

  return STANDARD_DISTANCES
    .filter(d => d <= Math.max(...runs.map(a => a.distance_meters)))
    .map(dist => {
      const efforts = runs
        .filter(a => a.distance_meters >= dist)
        .map(a => ({
          distance_meters: dist,
          elapsed_ms: Math.round((a.average_pace_seconds_per_km / 1000) * dist * 1000),
          activity_id: a.id,
          activity_name: a.name,
          achieved_at: a.start_at,
        }))
        .sort((a, b) => a.elapsed_ms - b.elapsed_ms)
        .slice(0, 3);
      return { distance_meters: dist, efforts };
    });
}

