// ── Year Review ───────────────────────────────────────────────────────────────

export function getYearReview(year) {
  const y = parseInt(year, 10);
  const acts = ACTIVITIES.filter(a => parseInt(a.start_at.slice(0, 4), 10) === y);
  if (!acts.length) return null;

  const byMonth = Array.from({ length: 12 }, (_, m) => {
    const monthActs = acts.filter(a => parseInt(a.start_at.slice(5, 7), 10) === m + 1);
    return {
      month: m + 1,
      distance_meters: monthActs.reduce((s, a) => s + a.distance_meters, 0),
      activity_count: monthActs.length,
    };
  });

  const biggestAct = [...acts].sort((a, b) => b.distance_meters - a.distance_meters)[0];
  const runs  = acts.filter(a => a.sport_type === "run");
  const rides = acts.filter(a => a.sport_type === "ride");

  return {
    year: y,
    total_distance_meters: acts.reduce((s, a) => s + a.distance_meters, 0),
    total_elapsed_ms: acts.reduce((s, a) => s + a.elapsed_ms, 0),
    total_elevation_meters: acts.reduce((s, a) => s + (a.elevation_gain_meters || 0), 0),
    total_activities: acts.length,
    prs_set: 3,
    by_sport: [
      { sport_type: "run",  activity_count: runs.length,  distance_meters: runs.reduce((s,a)=>s+a.distance_meters,0) },
      { sport_type: "ride", activity_count: rides.length, distance_meters: rides.reduce((s,a)=>s+a.distance_meters,0) },
    ],
    by_month: byMonth,
    biggest_activity: biggestAct ? { id: biggestAct.id, name: biggestAct.name, start_at: biggestAct.start_at, distance_meters: biggestAct.distance_meters } : undefined,
    most_used_gear: { id: "gear-001", name: "Nike Pegasus 41", activity_count: runs.length, distance_meters: runs.reduce((s,a)=>s+a.distance_meters,0) },
  };
}

